# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İLAHİ SIFATLAR BAĞLAMINDA KADER VE KAZA İNANCININ YAPISI</text>\n  <rect x="25" y="50" width="310" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="75" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#1e40af">KADER (Ezelî Ölçü, Plan ve Takdir)</text>\n  <rect x="42" y="90" width="276" height="58" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="110" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">İlim Sıfatı (Kuşatıcı Bilgi)</text>\n  <text x="180" y="128" text-anchor="middle" font-size="10.5" fill="#334155">Allah\'ın olmuş ve olacak her şeyi</text>\n  <text x="180" y="142" text-anchor="middle" font-size="10.5" fill="#334155">ezelde tüm ayrıntılarıyla bilmesi</text>\n  <rect x="42" y="160" width="276" height="65" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="180" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">İrade Sıfatı (Dileme ve Tahsis)</text>\n  <text x="180" y="198" text-anchor="middle" font-size="10.5" fill="#334155">Mümkün olan seçeneklerden birini</text>\n  <text x="180" y="212" text-anchor="middle" font-size="10.5" fill="#334155">belirli bir ölçü ve hikmetle dilemesi</text>\n\n  <rect x="365" y="50" width="310" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="75" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#166534">KAZA (Zamanı Gelince Yaratma)</text>\n  <rect x="382" y="90" width="276" height="58" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="110" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">Kudret Sıfatı (Sonsuz Güç)</text>\n  <text x="520" y="128" text-anchor="middle" font-size="10.5" fill="#334155">Takdir edilen varlık ve olayları</text>\n  <text x="520" y="142" text-anchor="middle" font-size="10.5" fill="#334155">varlık alanına çıkarma kudreti</text>\n  <rect x="382" y="160" width="276" height="65" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="180" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">Tekvin Sıfatı (Yoktan Var Etme)</text>\n  <text x="520" y="198" text-anchor="middle" font-size="10.5" fill="#334155">Zamanı ve şartları geldiğinde</text>\n  <text x="520" y="212" text-anchor="middle" font-size="10.5" fill="#334155">planlanan olayı fiilen yaratması</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İNSAN FİİLLERİNİN TASNİFİ VE AHLAKİ SORUMLULUK (KESB - HALK)</text>\n  <rect x="25" y="50" width="310" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">1. Iztırârî (Zorunlu) Fiiller</text>\n  <text x="40" y="104" font-size="11" fill="#78350f">• İnsanın seçimi ve iradesi dışında gerçekleşir.</text>\n  <text x="40" y="128" font-size="11" fill="#78350f">• Kalp atışı, göz rengi, refleksler, doğum yeri.</text>\n  <text x="40" y="152" font-size="11" fill="#78350f">• Doğrudan küllî irade ve kudretle yaratılır.</text>\n  <rect x="45" y="175" width="270" height="46" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="180" y="196" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b45309">Hüküm: Teklif ve Sorumluluk Yoktur</text>\n  <text x="180" y="212" text-anchor="middle" font-size="10" fill="#78350f">Sevap veya günah konusu olmaz.</text>\n\n  <rect x="365" y="50" width="310" height="190" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="520" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">2. İhtiyârî (İradeli) Fiiller</text>\n  <text x="380" y="104" font-size="11" fill="#4c1d95">• Akıl ve cüz\'î iradeyle seçilerek yapılır.</text>\n  <text x="380" y="128" font-size="11" fill="#4c1d95">• İbadet etmek, iyilik yapmak, dürüst olmak.</text>\n  <text x="380" y="152" font-size="11" fill="#4c1d95">• Kul iradesiyle seçer (Kesb), Allah yaratır (Halk).</text>\n  <rect x="385" y="175" width="270" height="46" rx="6" fill="#ffffff" stroke="#8b5cf6" stroke-width="1.5"/>\n  <text x="520" y="196" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6d28d9">Hüküm: Ahlaki ve Dini Sorumluluk Vardır</text>\n  <text x="520" y="212" text-anchor="middle" font-size="10" fill="#4c1d95">Dünya ve ahirette karşılığı (sevap/ceza) görülür.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KELAM EKOLLERİNİN İRADE VE KADER ANLAYIŞLARI</text>\n  <rect x="20" y="50" width="205" height="190" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="122" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b91c1c">Cebriyye (Mutlak Cebir)</text>\n  <text x="32" y="100" font-size="10.5" fill="#334155">• İnsanın iradesi ve seçme gücü</text>\n  <text x="40" y="116" font-size="10.5" fill="#475569">yoktur (Rüzgârdaki yaprak).</text>\n  <text x="32" y="140" font-size="10.5" fill="#334155">• Tüm fiilleri zorunlu olarak</text>\n  <text x="40" y="156" font-size="10.5" fill="#475569">Allah yaptırır.</text>\n  <text x="32" y="180" font-size="10.5" font-weight="bold" fill="#991b1b">• Eleştiri: Ahlaki sorumluluğu</text>\n  <text x="40" y="196" font-size="10.5" font-weight="bold" fill="#991b1b">ve ilahi adaleti geçersiz kılar.</text>\n\n  <rect x="247" y="50" width="206" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="2.2"/>\n  <text x="350" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Ehl-i Sünnet (Dengeli Orta Yol)</text>\n  <text x="259" y="100" font-size="10.5" fill="#334155">• İnsan akıl ve cüz\'î irade</text>\n  <text x="267" y="116" font-size="10.5" fill="#475569">sahibidir; özgürce seçer.</text>\n  <text x="259" y="140" font-size="10.5" fill="#334155">• Kul fiili kesb eder (kazanır),</text>\n  <text x="267" y="156" font-size="10.5" fill="#475569">Allah ise halk eder (yaratır).</text>\n  <text x="259" y="180" font-size="10.5" font-weight="bold" fill="#166534">• Hem ilahi kudret hem de</text>\n  <text x="267" y="196" font-size="10.5" font-weight="bold" fill="#166534">insani sorumluluk korunur.</text>\n\n  <rect x="475" y="50" width="205" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="577" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Mu\'tezile (Mutlak Özgürlük)</text>\n  <text x="487" y="100" font-size="10.5" fill="#334155">• İnsan kendi fiillerinin hem</text>\n  <text x="495" y="116" font-size="10.5" fill="#475569">seçicisi hem yaratıcısıdır.</text>\n  <text x="487" y="140" font-size="10.5" fill="#334155">• İhtiyârî fiillerde ilahi irade</text>\n  <text x="495" y="156" font-size="10.5" fill="#475569">ve yaratma müdahil olmaz.</text>\n  <text x="487" y="180" font-size="10.5" font-weight="bold" fill="#1e40af">• Eleştiri: Allah\'ın mutlak</text>\n  <text x="495" y="196" font-size="10.5" font-weight="bold" fill="#1e40af">yaratıcılığını (Hâlık) sınırlar.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
